sp_widget.client_script:
api.controller = function($scope, $window, $location) {
  var c = this;

  // Arrays to hold uploaded attachment info
  c.ownershipStructureAttachments = [];
  c.signingArrangementAttachments = [];
  c.idvUboAttachments = [];
  c.constitutionDocAttachments = [];

  c.selectedFiles = {};

  // ---------------- Helper: Convert file → Base64 ----------------
  function toBase64(file, callback) {
    var reader = new FileReader();
    reader.onload = function(e) {
      var base64 = e.target.result.split(",")[1];
      callback(base64);
    };
    reader.readAsDataURL(file);
  }

  // ---------------- Generic uploader ----------------
  function uploadFile(inputId, prefix, fieldName, targetArray, callback) {
    var input = document.getElementById(inputId);
    if (!input.files.length) {
      if (callback) callback(); // continue if no file
      return;
    }
    var file = input.files[0];
    toBase64(file, function(base64String) {
      c.server.get({
        action: "upload",
        recordSysId: c.data.recordSysId,
        fileName: prefix + file.name,
        fileType: file.type,
        fileContent: base64String,
        fieldName: fieldName
      }).then(function(response) {
        if (response.data.success) {
          $scope.$applyAsync(function() {
            targetArray.push({
              file_name: file.name,
              sys_id: response.data.attachmentSysId
            });
          });
          if (callback) callback(); // continue after upload
        } else {
          alert("Upload failed for " + file.name + ": " + response.data.error);
        }
      });
    });
  }

  // ---------------- Remove file ----------------
  c.removeFile = function(targetArray, index) {
    targetArray.splice(index, 1);
  };

  // ---------------- Validation ----------------
  c.validateForm = function() {
    if (!c.ownershipStructureAttachments.length && !document.getElementById("ownership-structure").files.length) {
      alert("Please upload Ownership Structure."); return false;
    }
    if (!c.signingArrangementAttachments.length && !document.getElementById("signing-arrangement").files.length) {
      alert("Please upload Signing Arrangement – Board Resolution."); return false;
    }
    if (!c.idvUboAttachments.length && !document.getElementById("idv-ubo").files.length) {
      alert("Please upload ID&V of UBO, Controller."); return false;
    }
    if (!c.constitutionDocAttachments.length && !document.getElementById("constitution-doc").files.length) {
      alert("Please upload Constitution Doc - COI."); return false;
    }
    return true;
  };

  // ---------------- Save Draft ----------------
  c.saveDraft = function() {
    var draftData = {
      ownershipStructureAttachments: c.ownershipStructureAttachments,
      signingArrangementAttachments: c.signingArrangementAttachments,
      idvUboAttachments: c.idvUboAttachments,
      constitutionDocAttachments: c.constitutionDocAttachments
    };
    c.server.get({
      action: "saveDraft",
      recordSysId: c.data.recordSysId,
      draft: JSON.stringify(draftData)
    }).then(function(response) {
      if (response.data.success) {
        alert("Draft saved successfully!");
      } else {
        alert("Failed to save draft: " + response.data.error);
      }
    });
  };

  // ---------------- Proceed ----------------
  c.proceed = function() {
    if (!c.validateForm()) return;

    // Upload all files in sequence
    uploadFile("ownership-structure", "OWN_", "ownership_structure", c.ownershipStructureAttachments, function() {
      uploadFile("signing-arrangement", "SIGN_", "signing_arrangement_board_resolution", c.signingArrangementAttachments, function() {
        uploadFile("idv-ubo", "IDV_", "id_v_of_ubo_controller", c.idvUboAttachments, function() {
          uploadFile("constitution-doc", "COI_", "constitution_doc_coi", c.constitutionDocAttachments, function() {
            finishProceed();
          });
        });
      });
    });

    function finishProceed() {
      alert("All documents uploaded successfully. Moving to next step...");
      $location.url = "/fcc_kyc?id=entity_video_kyc";
    }
  };
};

sp_widget.css:
body {
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 0;
}

/* Breadcrumb Header */
.breadcrumb-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px 20px;
  border-bottom: 1px solid #ccc;
  background-color: #fff; /* white background */
}

.breadcrumb {
  font-size: 14px;
  color: #333;
  font-weight: bold;
}

.step-info {
  text-align: right;
  font-size: 14px;
  color: #333;
}

/* Section Title */
.section-title {
  text-align: center;
  font-size: 20px;
  font-weight: bold;
  margin: 20px 0;
  color: #333;
}

/* Document Layout */
.document-upload-layout {
  display: flex;
  flex-direction: column;
  gap: 25px;
  padding: 20px;
  background-color: #fff;
}

.upload-row {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-bottom: 25px;
}

.upload-row label {
  font-weight: bold;
  font-size: 16px;
  color: #333;
  min-width: 150px;
}

.input-group {
  display: flex;
  align-items: center;
  gap: 20px;
  flex: 1;
}

.uniform-select {
  width: 250px;  /* uniform dropdown width */
  padding: 6px;
  font-size: 14px;
  border: 1px solid #ccc;
  border-radius: 4px;
}

/* Buttons */
.button-container {
  display: flex;
  justify-content: flex-end;
  gap: 15px;
  padding: 20px;
  background-color: #fff;
}

.button-container button {
  padding: 10px 20px;
  font-size: 14px;
  font-weight: bold;
  color: white;
  background-color: #2563eb;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.button-container button:hover {
  background-color: #1e3a8a;
}

h3 {
  color: #1e3a8a;
  margin-bottom: 10px;
}

/* Checkbox Question */
.question-container {
  text-align: left;
  padding: 20px;
  background-color: #f8f9fa;
  border-top: 1px solid #ccc;
}

.question-container label {
  font-size: 15px;
  font-weight: bold;
  cursor: pointer;
}

.question-container input[type="checkbox"] {
  margin-right: 8px;
}

.only-holder-question {
  padding: 10px 20px;
  font-size: 14px;
  font-weight: bold;
  color: #333;
}

.required {
  color: red;
  font-weight: bold;
  margin-left: 3px;
}

sp_widget.script:
(function($sp) { 
  // Get recordSysId from user email
  var email_ind = gs.getUser().getEmail();
  var gr_rr = new GlideRecordSecure('x_vuram_financia_0_fcc_kyc_entity_details');
  gr_rr.addQuery('email_id', email_ind);
  gr_rr.query();
  if (gr_rr.next()) {
    data.recordSysId = gr_rr.sys_id + "";
  }

  // ---------------- Upload ----------------
  if (input && input.action === "upload") {
    try {
      var gr = new GlideRecordSecure("x_vuram_financia_0_fcc_kyc_entity_details");
      if (gr.get(input.recordSysId)) {
        var gsa = new GlideSysAttachment();
        var attachmentSysId = gsa.writeBase64(
          gr,
          input.fileName,   // filename
          input.fileType,   // MIME type
          input.fileContent // Base64 string
        );

        // map uploaded file to the correct field
        if (input.fieldName && gr.isValidField(input.fieldName)) {
          gr.setValue(input.fieldName, attachmentSysId);
          gr.update();
        }

        data.success = true;
        data.attachmentSysId = attachmentSysId;
      } else {
        data.success = false;
        data.error = "Record not found: " + input.recordSysId;
      }
    } catch (e) {
      data.success = false;
      data.error = e.message;
    }
  }

  // ---------------- Save Draft ----------------
  if (input && input.action === "saveDraft") {
    try {
      var draftGr = new GlideRecordSecure("x_vuram_financia_0_fcc_kyc_entity_details");
      if (draftGr.get(input.recordSysId)) {
        // Option 1: store everything as JSON in one field
        if (draftGr.isValidField("u_draft_data")) {
          draftGr.u_draft_data = input.draft;
        }

        // Option 2: map individual fields if they exist
        if (input.ownershipStructureAttachments && draftGr.isValidField("ownership_structure"))
          draftGr.ownership_structure = input.ownershipStructureAttachments.length ? input.ownershipStructureAttachments[0].sys_id : "";

        if (input.signingArrangementAttachments && draftGr.isValidField("signing_arrangement_board_resolution"))
          draftGr.signing_arrangement_board_resolution = input.signingArrangementAttachments.length ? input.signingArrangementAttachments[0].sys_id : "";

        if (input.idvUboAttachments && draftGr.isValidField("id_v_of_ubo_controller"))
          draftGr.id_v_of_ubo_controller = input.idvUboAttachments.length ? input.idvUboAttachments[0].sys_id : "";

        if (input.constitutionDocAttachments && draftGr.isValidField("constitution_doc_coi"))
          draftGr.constitution_doc_coi = input.constitutionDocAttachments.length ? input.constitutionDocAttachments[0].sys_id : "";

        draftGr.update();

        data.success = true;
      } else {
        data.success = false;
        data.error = "Record not found for draft save: " + input.recordSysId;
      }
    } catch (e) {
      data.success = false;
      data.error = e.message;
    }
  }

  // ---------------- Map Attachment (optional hook) ----------------
  if (input && input.action === "mapAttachment") {
    data.success = true;
    data.attachmentSysId = data.attachmentSysId || "";
  }
})($sp);
